mapper.select:
SELECT COUNT(*) FROM pilots p

    AND p.topic ILIKE '%' || #{topic} || '%'
    AND p.status = #{status}
    AND p.priority = #{priority}
    AND p.assignee_id = #{assigneeId}

        AND (p.title ILIKE '%' || #{keyword} || '%' OR p.content ILIKE '%' || #{keyword} || '%' OR p.topic ILIKE '%' || #{keyword} || '%')

    AND p.is_archived = #{isArchived}
    AND p.is_archived = false

mapper.update:
UPDATE pilots SET is_archived = #{isArchived}, updated_at = CURRENT_TIMESTAMP
WHERE id IN
#{id}
